#if UNITY_EDITOR
using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace ElswordPixel.Editor.BelowBackgroundControlledV21 {
 [InitializeOnLoad] public static class Worker {
  const string Active="Elsword.BelowBackground.Active",Pending="Elsword.BelowBackground.Pending",Output="Elsword.BelowBackground.Output",Bundle="Elsword.BelowBackground.Bundle";static bool fault;static int phase,readyFrame;
  static Worker(){if(SessionState.GetBool(Active,false))Attach();}
  static void Attach(){EditorApplication.update-=Poll;EditorApplication.update+=Poll;Application.logMessageReceived-=Logged;Application.logMessageReceived+=Logged;}
  static void Logged(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)fault=true;}
  public static void Run(){if(!Application.isBatchMode||EditorApplication.isPlaying||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new InvalidOperationException("Idle batch Editor required");string output=Environment.GetEnvironmentVariable("EL_BELOW_BACKGROUND_OUTPUT"),bundle=Environment.GetEnvironmentVariable("EL_BELOW_BACKGROUND_BUNDLE");if(string.IsNullOrEmpty(output)||string.IsNullOrEmpty(bundle)||Directory.Exists(output))throw new InvalidOperationException("Fresh explicit background fixture output required");Directory.CreateDirectory(output);SessionState.SetString(Output,output);SessionState.SetString(Bundle,bundle);SessionState.SetBool(Active,true);SessionState.SetBool(Pending,true);fault=false;Attach();EditorSceneManager.OpenScene(DemoBuilder.ScenePath);EditorApplication.isPlaying=true;}
  static void Poll(){if(fault){Finish(2);return;}if(!EditorApplication.isPlaying||EditorApplication.isCompiling)return;var scene=UnityEngine.Object.FindFirstObjectByType<DemoScene>();if(!scene)return;try{string output=SessionState.GetString(Output,"");if(SessionState.GetBool(Pending,false)){SessionState.SetBool(Pending,false);scene.enabled=false;scene.BeginBelowBackgroundComponentV21(SessionState.GetString(Bundle,""),output,0);phase=0;readyFrame=Time.frameCount+2;return;}if(Time.frameCount<readyFrame)return;switch(phase){case 0:scene.CaptureBelowBackgroundPairV21("room1-entry");scene.FinishBelowBackgroundCaseV21();break;case 1:scene.BeginBelowBackgroundComponentV21(SessionState.GetString(Bundle,""),output,2);break;case 2:scene.CaptureBelowBackgroundPairV21("boss-entry");scene.StepBelowFortCameraComponentFixtureV21(180);break;case 3:scene.CaptureBelowBackgroundPairV21("boss-3s");scene.StepBelowFortCameraComponentFixtureV21(420);break;case 4:scene.CaptureBelowBackgroundPairV21("boss-10s");scene.FinishBelowBackgroundCaseV21();break;case 5:var result=scene.FinishBelowBackgroundComponentV21();File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(result,true));Finish(result.passed&&!fault?0:2);return;}phase++;readyFrame=Time.frameCount+2;}catch(Exception e){File.WriteAllText(Path.Combine(SessionState.GetString(Output,""),"failure.txt"),e.ToString());Debug.LogException(e);Finish(2);}}
  static void Finish(int code){SessionState.SetBool(Active,false);SessionState.SetBool(Pending,false);EditorApplication.update-=Poll;Application.logMessageReceived-=Logged;EditorApplication.Exit(code);}
 }
}
#endif
